import type { Database } from "@/types/database";

type Marina = Database["public"]["Tables"]["marinas"]["Row"];
type Slip = Database["public"]["Tables"]["slips"]["Row"] & {
  marinas: Marina;
};

const now = new Date().toISOString();

function makeMarina(
  id: string,
  owner_id: string,
  name: string,
  address: string,
  city: string,
  state: string,
  zip: string | null,
  lat: number | null,
  lng: number | null,
  phone: string | null,
  website: string | null,
): Marina {
  return {
    id, owner_id, name, description: null, address, city, state, zip, lat, lng,
    amenities: [], photos: [], phone, email: null, website,
    is_active: true, stripe_account_id: null, stripe_onboarding_complete: false,
    payouts_enabled: false, created_at: now, updated_at: now,
  };
}

